    # The colored horizontal bars partition the picture.  The lower glyphs leave
    # a trail (3) while the still-leading pixels retain their original colour.
    a=[r[:] for r in g]
    h=len(a); w=len(a[0])
    # retain bars and repaint the old (non-leading) 4 glyph pixels
    for i in range(h):
        for j in range(w):
            if a[i][j]==4:
                a[i][j]=3
    # leading edge of each 4-component advances one square to the right
    seen=set()
    for i in range(h):
      for j in range(w):
       if g[i][j]!=4 or (i,j) in seen: continue
       q=[(i,j)]; seen.add((i,j)); comp=[]
       while q:
        x,y=q.pop(); comp.append((x,y))
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
         z=(x+dx,y+dy)
         if 0<=z[0]<h and 0<=z[1]<w and g[z[0]][z[1]]==4 and z not in seen: seen.add(z);q.append(z)
       # cells on the upper/right-facing contour advance
       for x,y in comp:
        if (x-1,y) not in comp and y+1<w and g[x][y+1]==0:
         a[x][y+1]=4
    return a"}

